package app.truemotion.vector;
import java.util.*;
import org.json.*;
import org.mozilla.javascript.*;
import org.mozilla.javascript.ast.*;
import org.mozilla.javascript.debug.*;

/** Interpreted JavaScript for vector geometry, with no Java/OS bridge. */
public final class VectorProgram {
    static final class Budget {long start=System.nanoTime();int instructions;final ArrayDeque<Scriptable> scopes=new ArrayDeque<Scriptable>();void check(){if(System.nanoTime()-start>80_000_000L||instructions>30000)throw new Limit("Vector script exceeded its frame budget");for(Scriptable scope:scopes)for(Object id:scope.getIds()){Object value=id instanceof String?scope.get((String)id,scope):null;if(value instanceof CharSequence&&((CharSequence)value).length()>262144||value instanceof NativeArray&&((NativeArray)value).getLength()>16384)throw new Limit("Vector script value is too large");}}}
    static final class Limit extends Error {Limit(String message){super(message);}}
    static final ThreadLocal<Budget> budget=new ThreadLocal<Budget>();
    static final ContextFactory factory=new ContextFactory(){
        @Override protected Context makeContext(){Context c=super.makeContext();c.setOptimizationLevel(-1);c.setLanguageVersion(Context.VERSION_ES6);c.setInstructionObserverThreshold(50);c.setMaximumInterpreterStackDepth(64);c.setClassShutter(name->false);c.setGeneratingDebug(true);c.setDebugger(new Debugger(){public void handleCompilationDone(Context cx,DebuggableScript script,String source){}public DebugFrame getFrame(Context cx,DebuggableScript script){return new DebugFrame(){Scriptable activation;public void onEnter(Context c,Scriptable a,Scriptable self,Object[] args){activation=a;budget.get().scopes.addLast(a);budget.get().check();}public void onLineChange(Context c,int line){budget.get().check();}public void onExceptionThrown(Context c,Throwable e){}public void onExit(Context c,boolean throwing,Object result){budget.get().scopes.removeLastOccurrence(activation);}public void onDebuggerStatement(Context c){}};}},null);return c;}
        @Override protected void observeInstructionCount(Context c,int count){Budget b=budget.get();b.instructions+=count;b.check();}
    };
    static final String BOOTSTRAP="var objects=JSON.parse(__input);var stage={width:__width,height:__height,currentFrame:frame,getChildByName:function(n){for(var i=0;i<objects.length;i++)if(objects[i].name===n||objects[i].id===n)return objects[i];return null;}};var $=function(n){return stage.getChildByName(n);};var __control={target:-1,stop:false};stage.gotoAndStop=function(n){__control.target=Math.floor(n)-1;__control.stop=true;};stage.gotoAndPlay=function(n){__control.target=Math.floor(n)-1;__control.stop=false;};stage.stop=function(){__control.stop=true;};stage.play=function(){__control.stop=false;};var gotoAndStop=stage.gotoAndStop,gotoAndPlay=stage.gotoAndPlay,stop=stage.stop,play=stage.play;for(var i=0;i<objects.length;i++){(function(o){[['rotation','angle'],['scaleX','sx'],['scaleY','sy'],['alpha','opacity']].forEach(function(k){Object.defineProperty(o,k[0],{get:function(){return o[k[1]];},set:function(v){o[k[1]]=v;}});});})(objects[i]);}eval=undefined;RegExp=undefined;Date=undefined;var __fp=Function.prototype;__fp.constructor=function(){throw Error('Dynamic compilation is unavailable');};Function=__fp.constructor;Function.prototype=__fp;String.prototype.repeat=function(n){n=Math.floor(n);if(n<0||n>8192||this.length*n>262144)throw Error('String exceeds frame budget');var result='';while(n-->0)result+=this;return result;};String.prototype.match=String.prototype.search=function(){throw Error('Regular expressions are unavailable in vector scripts');};var __seed=(frame*1664525+1013904223)>>>0;Math.random=function(){__seed=(Math.imul(__seed,1664525)+1013904223)>>>0;return __seed/4294967296;};";
    public static ArrayList<VectorDocument.Shape> apply(VectorDocument doc,int index,List<VectorDocument.Shape> original){
        if(doc.script.length()>32768)throw new IllegalArgumentException("Vector script exceeds 32K characters");Budget b=new Budget();budget.set(b);Context cx=factory.enterContext();try{
            AstRoot ast=new Parser().parse(doc.script,"vector-script",1);ast.visit(n->{if(n.getType()==Token.REGEXP)throw new Limit("Regular expressions are unavailable in vector scripts");return true;});
            ScriptableObject scope=cx.initSafeStandardObjects();JSONArray data=new JSONArray();for(VectorDocument.Shape s:original)data.put(s.json());ScriptableObject.putProperty(scope,"__input",data.toString());ScriptableObject.putProperty(scope,"__width",doc.width);ScriptableObject.putProperty(scope,"__height",doc.height);ScriptableObject.putProperty(scope,"time",index/doc.fps);ScriptableObject.putProperty(scope,"frame",index+1);ScriptableObject.putProperty(scope,"fps",doc.fps);ScriptableObject.putProperty(scope,"dt",1/doc.fps);
            b.start=System.nanoTime();cx.evaluateString(scope,BOOTSTRAP,"vector-api",1,null);cx.evaluateString(scope,"(function(){\n"+doc.script+"\n}).call(stage);","vector-script",1,null);Object text=cx.evaluateString(scope,"JSON.stringify({objects:objects,control:__control})","vector-result",1,null);String json=Context.toString(text);if(json.length()>4*1024*1024)throw new Limit("Vector output exceeds frame budget");JSONObject result=new JSONObject(json);JSONArray array=result.getJSONArray("objects");if(array.length()>16384)throw new Limit("Too many scripted objects");ArrayList<VectorDocument.Shape> shapes=new ArrayList<VectorDocument.Shape>();for(int i=0;i<array.length();i++){VectorDocument.Shape shape=VectorDocument.Shape.read(array.getJSONObject(i));for(VectorDocument.Shape old:original)if(old.id.equals(shape.id)&&old.image.equals(shape.image)&&Arrays.equals(old.imageRect,shape.imageRect))shape.imageUri=old.imageUri;shapes.add(shape);}
            VectorDocument test=new VectorDocument(doc.width,doc.height,doc.fps,1);test.tracks.get(0).keys.get(0).shapes.addAll(shapes);test.images=doc.images;test.symbols=doc.symbols;test.validate();JSONObject control=result.getJSONObject("control");doc.scriptTarget=control.optInt("target",-1);doc.scriptStop=control.optBoolean("stop");return shapes;
        }catch(Throwable e){throw new IllegalArgumentException("JavaScript: "+(e.getMessage()==null?e.toString():e.getMessage()),e);}finally{Context.exit();budget.remove();}
    }
}
